def solution(to_currency, values):
    exchange_rate = 1.1363636
    formatted_values = []
    for value in values:
        if to_currency == 'USD':
            converted_value = round(value * exchange_rate, 2)
            formatted_values.append(f'${converted_value:,.2f}')
        elif to_currency == 'EUR':
            converted_value = round(value / exchange_rate, 2)
            formatted_values.append(f'{converted_value:,.2f}€')
    return formatted_values
